/*!
 * Tavola — Bootstrap 6 restaurant template
 *
 * Design language: the menu is the product, so the menu is the page. Deep green
 * canvas, terracotta accent, and dish rows set with leader dots the way a
 * printed menu sets them — which is the one typographic detail that makes a
 * restaurant site read as a restaurant rather than a generic business site.
 *
 * Deliberately distinct from Lantern (cream, serif, hospitality-calm): this one
 * is darker, denser, and organised around service times rather than rooms.
 */

:root {
  --brand: oklch(58% 0.13 35);
  --kit-section-y: 5rem;
  --tavola-ink: oklch(26% 0.03 155);
}

@media (width >= 768px) { :root { --kit-section-y: 7rem; } }

[data-bs-theme="light"] {
  --bs-bg-body: oklch(97.5% 0.008 120);
  --bs-bg-2: oklch(94% 0.012 120);
}

[data-bs-theme="dark"] {
  --bs-bg-body: oklch(20% 0.018 155);
  --bs-bg-2: oklch(24% 0.02 155);
}

.display-serif,
.section-title,
.dish-name {
  font-family: ui-serif, Georgia, "Times New Roman", serif;
  font-weight: 400;
  letter-spacing: -0.012em;
}

/* ---------------------------------------------------------------
   Header + hero
   --------------------------------------------------------------- */

.top-note {
  background: var(--tavola-ink);
  color: oklch(96% 0.01 120);
  font-size: 0.8125rem;
  padding-block: 0.5rem;
  text-align: center;
}

.top-note a { color: inherit; font-weight: 600; }

.wordmark {
  font-family: ui-serif, Georgia, serif;
  font-size: 1.5rem;
  letter-spacing: 0.06em;
  text-decoration: none;
}

.hero {
  position: relative;
  isolation: isolate;
  padding-block: clamp(3.5rem, 8vw, 6rem);
  overflow: hidden;
}

.hero > .hero-bg {
  position: absolute;
  inset: 0;
  z-index: -2;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 55%;
}

.hero::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(
    to right,
    color-mix(in oklab, var(--bs-bg-body), transparent 5%) 0%,
    color-mix(in oklab, var(--bs-bg-body), transparent 20%) 46%,
    color-mix(in oklab, var(--bs-bg-body), transparent 55%) 100%);
}

.hero-title { font-size: clamp(2.5rem, 1.2rem + 5.2vw, 5rem); line-height: 1.02; text-wrap: balance; }

.eyebrow-rule {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--bs-fg-primary);
}

.eyebrow-rule::before {
  content: "";
  width: 2.5rem;
  height: 1px;
  background: currentcolor;
}

/* ---------------------------------------------------------------
   Menu — the identity piece
   --------------------------------------------------------------- */

.menu-card {
  padding: clamp(1.5rem, 4vw, 3rem);
  background: var(--bs-bg-2);
  border: 1px solid var(--bs-border-color);
}

/* Dish rows with leader dots, set the way a printed menu sets them. The dots
   are a repeating-linear-gradient on a flexible middle cell, so they stretch to
   whatever gap is left and never wrap. */
.dish {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: baseline;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}

.dish-name { font-size: 1.15rem; }

.dish-leader {
  height: 1px;
  align-self: end;
  margin-bottom: 0.35rem;
  background-image: radial-gradient(circle, var(--bs-fg-3) 0.5px, transparent 0.6px);
  background-size: 6px 2px;
  background-repeat: repeat-x;
  background-position: bottom;
  opacity: 0.65;
}

.dish-price { font-variant-numeric: tabular-nums; font-weight: 600; }
.dish-note { color: var(--bs-fg-3); font-size: 0.875rem; margin-bottom: 1.25rem; max-width: 34rem; }

.dish-tags { display: inline-flex; gap: 0.35rem; margin-left: 0.5rem; }

.dish-tag {
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.1rem 0.4rem;
  border: 1px solid var(--bs-border-color);
  border-radius: var(--bs-radius-pill, 999px);
  color: var(--bs-fg-3);
  vertical-align: middle;
}

.course-label {
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--bs-fg-primary);
  padding-bottom: 0.6rem;
  margin-bottom: 1.5rem;
  border-bottom: 1px solid var(--bs-border-color);
}

/* ---------------------------------------------------------------
   Booking, hours, gallery
   --------------------------------------------------------------- */

.book-card {
  padding: clamp(1.5rem, 4vw, 2.25rem);
  background: var(--bs-bg-body);
  border: 1px solid var(--bs-border-color);
  border-top: 3px solid var(--bs-primary-base);
}

.hours-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.55rem 0;
  border-bottom: 1px solid var(--bs-border-color);
}

.hours-row:last-child { border-bottom: 0; }
.hours-row.is-today { color: var(--bs-fg-primary); font-weight: 600; }

.mosaic {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.6rem;
}

@media (width >= 768px) { .mosaic { grid-template-columns: repeat(4, 1fr); } }

.mosaic .ph { aspect-ratio: 1; }
.mosaic > *:first-child { grid-column: span 2; grid-row: span 2; }

.quote-block {
  border-left: 3px solid var(--bs-primary-base);
  padding-left: 1.25rem;
  font-family: ui-serif, Georgia, serif;
  font-size: 1.25rem;
  line-height: 1.5;
}

/* ---------------------------------------------------------------
   Sub page
   --------------------------------------------------------------- */

.sub-head {
  padding-block: 3.5rem;
  background: var(--bs-bg-2);
  border-bottom: 1px solid var(--bs-border-color);
}
